<?php use App\Support\Ui; $categories=['authentication'=>'Authentication','candidate'=>'Candidate lifecycle','booking'=>'Booking','rescheduling'=>'Rescheduling','cancellation'=>'Cancellation','resource'=>'Resource','support'=>'Support team','technology'=>'Technology','settings'=>'Settings']; ?>
<div class="page-heading"><div><span class="eyebrow">ACCOUNTABILITY</span><h1>Audit log</h1><p>Review administrative and booking activity without exposing sensitive values.</p></div></div>
<details class="mobile-filter-sheet"><summary><?= Ui::icon('filter') ?>Filters<?php $filterCount=count(array_filter($filters));if($filterCount):?><span><?= $e($filterCount) ?></span><?php endif;?></summary><form class="filter-bar audit-filters card" method="get"><div class="field"><label for="audit-from">From</label><input id="audit-from" type="date" name="date_from" value="<?= $e($filters['date_from']) ?>"></div><div class="field"><label for="audit-to">To</label><input id="audit-to" type="date" name="date_to" value="<?= $e($filters['date_to']) ?>"></div><div class="field"><label for="audit-actor">Actor</label><select id="audit-actor" name="actor_id"><option value="">All</option><?php foreach($actors as $actor):?><option value="<?= $e($actor['id']) ?>" <?= $filters['actor_id']==(string)$actor['id']?'selected':'' ?>><?= $e($actor['full_name']) ?></option><?php endforeach;?></select></div><div class="field"><label for="audit-category">Category</label><select id="audit-category" name="category"><option value="">All</option><?php foreach($categories as $value=>$label):?><option value="<?= $e($value) ?>" <?= $filters['category']===$value?'selected':'' ?>><?= $e($label) ?></option><?php endforeach;?></select></div><button class="button primary">Apply</button><a class="button secondary" href="<?= $e($url('admin/audit')) ?>">Clear</a></form></details>
<section class="card audit-directory"><div class="card-heading"><div><h2>Activity</h2><p><?= $e($result['total']) ?> event<?= $result['total']===1?'':'s' ?> · newest first</p></div></div><?php if(!$result['rows']):?><div class="empty-state"><h3>No activity matches the selected filters.</h3><p>Try a wider date range or clear the filters.</p></div><?php else:?><div class="table-scroll desktop-record-table"><table><thead><tr><th scope="col">Timestamp</th><th scope="col">Actor</th><th scope="col">Action</th><th scope="col">Entity</th><th scope="col">Summary</th><th scope="col"><span class="visually-hidden">Open</span></th></tr></thead><tbody><?php foreach($result['rows'] as $event):?><tr><td><span class="table-primary"><?= $e($event['created_local']->format('d M Y')) ?></span><span class="table-secondary"><?= $e($event['created_local']->format('H:i:s')) ?> IST</span></td><td><?= $e($event['actor_name']??'System') ?></td><td><span class="badge neutral"><?= $e($event['label']) ?></span></td><td><?= $e($event['entity_label']) ?></td><td><?= $e($event['summary']) ?></td><td><a class="row-link" aria-label="Open audit event" href="<?= $e($url('admin/audit/detail?id='.$event['id'])) ?>"><?= Ui::icon('chevron') ?></a></td></tr><?php endforeach;?></tbody></table></div>
<div class="mobile-record-list audit-mobile-list"><?php foreach($result['rows'] as $event):?><a class="mobile-record-card" href="<?= $e($url('admin/audit/detail?id='.$event['id'])) ?>"><div class="mobile-record-head"><time><?= $e($event['created_local']->format('d M Y · H:i:s')) ?> IST</time><span class="badge neutral"><?= $e($event['label']) ?></span></div><h3><?= $e($event['actor_name']??'System') ?></h3><p><?= $e($event['summary']) ?></p><div class="audit-entity"><span>Entity</span><strong><?= $e($event['entity_label']) ?></strong></div><span class="mobile-record-action">Open event <?= Ui::icon('chevron') ?></span></a><?php endforeach;?></div><?php endif;?></section><?= Ui::pagination($result,$filters,'Audit log pages') ?>
